echo "=== 1. Syntax check all modified Python files ===" && python3 - << 'PYEOF'
import filecmp, os, py_compile, sys
t, o = os.environ["TARGET_DIR"], os.environ["ORIGINAL_DIR"]
for d, dirs, fs in os.walk(t):
    dirs[:] = [x for x in dirs if x not in (".git", "__pycache__")]
    for f in fs:
        if not f.endswith(".py"):
            continue
        p = os.path.join(d, f)
        rel = os.path.relpath(p, t)
        q = os.path.join(o, rel)
        if not os.path.exists(q) or not filecmp.cmp(p, q, shallow=False):
            try:
                py_compile.compile(p, doraise=True)
            except Exception as e:
                print(f"Syntax error in {rel}: {e}")
                sys.exit(1)
print("Syntax: OK")
PYEOF && echo "" && echo "=== 2. Diff summary (files changed vs original) ===" && diff -rq --exclude="*.pyc" --exclude="*.egg-info" --exclude=".git" "$ORIGINAL_DIR" "$TARGET_DIR" 2>/dev/null | grep -E "^(Files|Only in)" || echo "(no differences)" && echo "" && echo "=== All checks passed ==="

